import itertools

def solve_n_queens(n=7):
    # Backtracking solver
    def is_safe(board, row, col):
        for r in range(row):
            c = board[r]
            if c == col or abs(c - col) == abs(r - row):
                return False
        return True

    def backtrack(row, board):
        if row == n:
            return board[:]
        for col in range(n):
            if is_safe(board, row, col):
                board.append(col)
                result = backtrack(row + 1, board)
                if result:
                    return result
                board.pop()
        return None

    return backtrack(0, [])

solution = solve_n_queens(7)
print(solution)

def verify(board):
    n = len(board)
    for i in range(n):
        for j in range(i+1, n):
            if board[i] == board[j] or abs(board[i] - board[j]) == abs(i - j):
                return False, f"Conflict between row {i} col {board[i]} and row {j} col {board[j]}"
    return True, "Valid"

board = [0, 2, 4, 6, 1, 3, 5]
print(verify(board))

